from datetime import datetime

class Chat:
    VALID_USER_KEY = 'valid_user'
    MESSAGE_FIELDS = ['sender', 'receiver', 'message', 'timestamp']
    TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"

    def __init__(self):
        self._users = {}

    @property
    def users(self):
        return self._users

    @users.setter
    def users(self, value):
        self._users = value

    def add_user(self, username):
        if self._is_user(username):
            return False
        self._users[username] = []
        return True

    def remove_user(self, username):
        if self._is_user(username):
            del self._users[username]
            return True
        return False

    def send_message(self, sender, receiver, message):
        if not self._both_users_exist(sender, receiver):
            return False

        message_info = self._create_message_info(sender, receiver, message)
        self._store_message(sender, receiver, message_info)
        return True

    def get_messages(self, username):
        if not self._is_user(username):
            return []
        return list(self._users[username])

    def _is_user(self, username):
        return username in self._users

    def _both_users_exist(self, sender, receiver):
        return self._is_user(sender) and self._is_user(receiver)

    def _create_message_info(self, sender, receiver, message):
        timestamp = datetime.now().strftime(self.TIMESTAMP_FORMAT)
        return {
            'sender': sender,
            'receiver': receiver,
            'message': message,
            'timestamp': timestamp
        }

    def _store_message(self, sender, receiver, message_info):
        self._users[sender].append(message_info)
        self._users[receiver].append(message_info)

